insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('b7ee2b77-4b11-450e-9f15-27faafa5449c', NULL, 'choose_meaning', 'Mẫu ngữ pháp nào có nghĩa: "Đi／Đến／Về (địa điểm) để làm gì (mục đích di chuyển)"?', 'V ています', 'V てはいけません', 'N1（Địa điểm）へ（に）+ V(masu gốc)に + 行きます／来ます／帰ります', 'V てください', 'N1（Địa điểm）へ（に）+ V(masu gốc)に + 行きます／来ます／帰ります', 'generated');
